figures.script:
diagram("direction: right
[Requirements] as r
[Design] as d
[Implementation] as i
[Testing] as t
[Deploy] as p
r -> d
d -> i
i -> t
t -> p
@0 r -> d
@1 d -> i
@2 i -> t
@3 t -> p
loop 1");

diagram("direction: right
[Plan] as p
[Risk analysis] as r
[Build] as b
[Evaluate] as e
p -> r
r -> b
b -> e
e -> p : next loop
@0 p -> r
@1 r -> b
@2 b -> e
@3 e -> p
loop 3");

diagram("mode: sequence
[Product owner] as po
[Team] as t
[Stakeholders] as s
po -> t : sprint backlog
t -> t : daily stand-up
t -> po : working increment
po -> s : sprint review
s --> po : feedback
po -> t : next sprint
@0 po -> t : sprint backlog
@1 t -> t : daily stand-up
@2 t -> po : working increment
@3 po -> s : sprint review
@4 s -> po : feedback");
